export class Dimension {
    static CreateNew(index, id = "") {
        return new Dimension({
            id,
            index,
            sectors: new Map(),
        });
    }
    constructor(data) {
        return Object.assign(this, data);
    }
    set(sectorId, region) {
        this.sectors.set(sectorId, region);
    }
    delete(sectorId) {
        this.sectors.delete(sectorId);
    }
    get(sectorId) {
        return this.sectors.get(sectorId);
    }
    getData() {
        return {
            id: this.id,
            index: this.index,
        };
    }
}
